class Car
{
  public:
    // Attribute
    string color;
    string model;

    // Method
    void startEngine()
    {
        cout << "Engine started" << endl;
    }
};

using namespace std;

// Define a class
class Car
{
  public:
    // Attribute
    string color;
    string model;

    // Method: starts the engine
    void startEngine()
    {
        cout << model << " engine started" << endl;
    }

    // Method: stops the engine
    void stopEngine()
    {
        cout << model << " engine stopped" << endl;
    }
};

int main()
{
    // Create first car object
    Car myCar;
    myCar.color = "Red";
    myCar.model = "Toyota";

    // Use attributes and methods
    cout << "My car color: " << myCar.color << endl;
    myCar.startEngine();
    myCar.stopEngine();

    return 0;
}

using namespace std;

// Class representing a Stack
class Stack {
  public:
    int arr[5];
    int top = -1;

    // Method to push element
    void push(int x) {
        if(top == 4) {
            cout << "Stack Overflow\n";
            return;
        }
        arr[++top] = x;
    }

    // Method to pop element
    void pop() {
        if(top == -1) {
            cout << "Stack Underflow\n";
            return;
        }
        top--;
    }

    // Method to display stack
    void display() {
        for(int i = top; i >= 0; i--) {
            cout << arr[i] << " ";
        }
        cout << endl;
    }
};

int main() {

    // Creating stack object
    Stack s;

    // Performing operations
    s.push(10);
    s.push(20);
    s.push(30);

    cout << "Stack elements: ";
    s.display();

    s.pop();

    cout << "After pop: ";
    s.display();

    return 0;
}

